import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireFlow Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireFlow/aireflow-v2-41-1.md","filePath":"aireblock-releases/AireFlow/aireflow-v2-41-1.md","lastUpdated":1790673158000}`),a={name:`aireblock-releases/AireFlow/aireflow-v2-41-1.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireflow-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireflow-icon.png"> AireFlow Release Notes</span> <a class="header-anchor" href="#aireflow-release-notes" aria-label="Permalink to “AireFlow Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> 2.41.1<br><strong>Release Date:</strong> 7th October 2026</p></blockquote><hr><h3 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li><strong>Improved Serialisation Handling</strong> (FLOW-625)</li><li><strong>Error Logging Enhancements</strong> (FLOW-1362)</li><li><strong>SPA Error Handling</strong> (FLOW-1361)</li><li><strong>Tenant Key Logging</strong> (FLOW-1360)</li><li><strong>Expression Input Styling</strong> (FLOW-1345)</li><li><strong>Enhanced API Security</strong> (FLOW-1322)</li></ul><hr><h3 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h3><h4 id="improved-serialisation-handling-flow-625" tabindex="-1">Improved Serialisation Handling (FLOW-625) <a class="header-anchor" href="#improved-serialisation-handling-flow-625" aria-label="Permalink to “Improved Serialisation Handling (FLOW-625)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The internal serialisation logic for the Workflow Engine now automatically manages the escaping of special characters for JSON and XML outputs. This fixes issues with certain inputs breaking mutations and removes the need for manual workarounds when mapped data contains line breaks, quotes, or HTML entities.</p></div><h4 id="error-logging-enhancements-flow-1362" tabindex="-1">Error Logging Enhancements (FLOW-1362) <a class="header-anchor" href="#error-logging-enhancements-flow-1362" aria-label="Permalink to “Error Logging Enhancements (FLOW-1362)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Resolved an issue where GraphQL cursor paging logic generated unnecessary error-level logs. The error is still returned through the API but without triggering internal error monitoring.</p></div><h4 id="spa-error-handling-flow-1361" tabindex="-1">SPA Error Handling (FLOW-1361) <a class="header-anchor" href="#spa-error-handling-flow-1361" aria-label="Permalink to “SPA Error Handling (FLOW-1361)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The system now handles the navigation requests for BFF containers and associated middleware stacks without writing unnecessary error logs.</p></div><h4 id="tenant-key-logging-flow-1360" tabindex="-1">Tenant Key Logging (FLOW-1360) <a class="header-anchor" href="#tenant-key-logging-flow-1360" aria-label="Permalink to “Tenant Key Logging (FLOW-1360)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Tenant key is now available in error logs, to allow developers to trace the source of any issues more easily.</p></div><h4 id="expression-input-styling-flow-1345" tabindex="-1">Expression Input Styling (FLOW-1345) <a class="header-anchor" href="#expression-input-styling-flow-1345" aria-label="Permalink to “Expression Input Styling (FLOW-1345)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Resolved a visual regression where typing in the Expression Name field would cause the entire page to shift during the evaluation preview. Task names are no longer previewed in the accordion title to prevent overflow, but the preview is still available within the task name field.</p></div><h4 id="enhanced-api-security-flow-1322" tabindex="-1">Enhanced API Security (FLOW-1322) <a class="header-anchor" href="#enhanced-api-security-flow-1322" aria-label="Permalink to “Enhanced API Security (FLOW-1322)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>A minor vulnerability in the Workflow Definition API has been fixed.</p></div>`,19)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};